with gaps as (select *, case when lag(event_time) over (partition by session_id order by event_time asc, id asc) is null or event_time > lag(event_time) over (partition by session_id order by event_time asc, id asc) + interval '60' day then 1 else 0 end as is_new_burst from web_events), islands as (select *, sum(is_new_burst) over (partition by session_id order by event_time asc, id asc rows between unbounded preceding and current row) as session_no from gaps) select s.id, s.session_id, s.event_type, s.page, s.event_time, (select avg(w2.duration_sec) from web_events w2 where w2.session_id = s.session_id) as avg_web_event_duration_sec from islands s order by event_type asc nulls first, id desc
